      "description": "Uses position_near_with_facing because this is a find/locate task. The player must navigate close to the orange tulip (placed at spawn-relative [8, 0, 8]) and face toward it, confirming they have visually located it among the scattered flowers. max_distance=16 allows detection from a reasonable viewing distance, and facing_tolerance=60 ensures the player is actually looking at the tulip.",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [8, 0, 8],
            "max_distance": 5,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
    {
      "task": "craft to light_gray_bed",
      "milestone_id": "craft_light_gray_bed",
      "description": "Uses inventory_has because the crafted light_gray_bed ends up in the player's inventory after crafting. The player retrieves materials (3 white_wool, 3 oak_planks, 1 light_gray_dye) from the nearby chest, crafts a white bed first, then combines it with light_gray_dye to produce the light_gray_bed. This is the most reliable check for craft completion.",
